-- Removes the FAQ feature's table. The public FAQ page and the admin FAQ editor
-- were already gone from the frontend, so the table was the last thing left.
-- The table was verified empty with no foreign keys in either direction before
-- this migration.
-- Rollback: restore the table from the pre-migration dump, or recreate it:
--   CREATE TABLE faqs (
--     id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
--     created_at TIMESTAMP(6), updated_at TIMESTAMP(6),
--     answer VARCHAR(2000) NOT NULL, question VARCHAR(255) NOT NULL,
--     display_order INTEGER NOT NULL
--   );

BEGIN;

DO $$
BEGIN
  IF (SELECT COUNT(*) FROM faqs) <> 0 THEN
    RAISE EXCEPTION 'faqs table is not empty; aborting drop';
  END IF;
END $$;

DROP TABLE IF EXISTS faqs;

COMMIT;
